// === Tab: mySketch ===
// PBa
// 2021-11-25
// Ed1
// Conformal Mapping of Polygon
//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

var init,act;         
var xc,yc;
var x,y;
var fact;
var alpha,dalpha;
var dbeta;
var tx,ty;
var htr;
var tabp=[];
var np,ns;
var rc;
var bz2,bz3,bsinz,bmob;
var map;


//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function setup()
{
   createCanvas(800, 800);
   cred=color(255,0,0);
   clred=color(200,80,80);
   cgreen=color(0,255,0);
   cblue=color(0,0,255);
   clblue=color(100,100,240);
   cbackg=color(200,200,255);
   cyellow=color(254,255,23);
   corange=color(234,214,28);
   cviolet=color(247,7,208);
   cwhite=color(255,255,255);
   cgrey=color(74,74,74);
   cblack=color(0,0,0);
   xc=400;
   yc=400;
   fact=100;
   frameRate(100000);
   textSize(14);
   rectMode(CENTER);
   htr=sqrt(3)/2;
   rc=1.5;
   dbeta=0.1;  

   bz2 = createButton('Map z*z');
   bz2.position(30, 100);
   bz2.style('background-color', cred);
   bz2.mousePressed(actBz2);

   bz3 = createButton('Map z*z*z');
   bz3.position(30, 140);
   bz3.style('background-color', cgreen);
   bz3.mousePressed(actBz3);

   bsinz = createButton('Map sin(z)');
   bsinz.position(30, 180);
   bsinz.style('background-color', corange);
   bsinz.mousePressed(actBsinz);

   bmobz = createButton('Map ((z-1)/(z+1))');
   bmobz.position(30, 220);
   bmobz.style('background-color', cyellow);
   bmobz.mousePressed(actBmobz);
   map=4;
   for(jj=0;jj<50;jj++)
      {
        tabp[jj]=createVector(0,0);
      }
  init=0;  
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function draw()
{
  act=1;
  if(init==0)
    {
      if(map==1)
        {
          np=12;
          ns=5;
        }
      else if(map==2)
        {
          np=12;
          ns=4;
        } 
      else if(map==3)
        {
          np=14;
          ns=7;
        }   
      else if(map==4)
        {
          np=15;
          ns=8;
        }
      dalpha=TAU/np;
      for(let n=0;n<np+1;n++)
        {
          let xs=rc*cos(n*dalpha + dbeta);
          let ys=rc*sin(n*dalpha + dbeta);
          tabp[n].x=xs;
          tabp[n].y=ys;  
        }
      act=0;
      init=1;      
    }

  if(init==1 & act==1)
    {      
      background(250,250,250);     
      textSize(28);
      fill(cblue);
      text("CONFORMAL MAPPING",180,50);
      stroke(cblack);
      textSize(17);
      strokeWeight(1);
      text("Click to change mapping",600,100);
      translate(xc,yc);
      fill(cyellow);
      circle(0,0,2*rc*fact);
      stroke(cblack);
      strokeWeight(2);
      line(-330,0,330,0);              // Axes
      line(0,-330,0,330);
      noFill();
      for(i=-3;i<4;i++)
        {
          fill(cblack);
          strokeWeight(1);
          affstring(i,i*fact,0,5,5);
          affstring(i,0,-i*fact,5,5);
        }
      stroke(cgreen);
      strokeWeight(2);
      for(n=0;n<np+1;n++)
        {
          circle(tabp[n].x*fact,tabp[n].y*fact,12);
        }    
     for(n=ns;n<np+1;n++)                                        
        {                                                        
          linepv(tabp[n],tabp[n-ns]);                            
          trlinepv(tabp[n],tabp[n-ns]);
        }
     dbeta=dbeta-0.01;
     init=0;
    }
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function actBz2()
{
  np=12;
  ns=5;
  dbeta=0.1;
  map=1;
  init=0;
}

function actBz3()
{
  np=11;
  ns=6;
  dbeta=0.1;
  map=2;
  init=0;
}

function actBsinz()
{
  np=14;
  ns=7;
  dbeta=0.1;
  map=3;
  init=0;
}

function actBmobz()
{
  np=8;
  ns=5;
  dbeta=0.1;
  map=4;
  init=0;
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function linepv(p,q)
{
  stroke(cgreen);
  line(p.x*fact,p.y*fact,q.x*fact,q.y*fact);
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function trlinepv(p,q)                                // Conformal transformation
{
  stroke(cblue);
  fill(cred);
  let k=(q.y-p.y)/(q.x-p.x);
  for(j=0;j<100;j++)
    {
      nx=p.x+j*(q.x-p.x)/100;
      ny=p.y+k*(nx-p.x);
      if(map==1)
        {
          tx=nx*nx-ny*ny;                              // Transform = z*z
          ty=2*nx*ny;
        }
      else if(map==2)
        {
          tx=nx*nx*nx-3*nx*ny*ny;                      // Transform= z*z*z
          ty=3*nx*nx*ny - ny*ny*ny;
        }
      else if(map==3)
        {
          tx=sin(1.2*nx)*cosh(1.2*ny);                 // Transform=sin(z)
          ty=-cos(1.2*nx)*sinh(1.2*ny);
          //tx=cos(nx)*cosh(ny);
          //ty=sin(nx)*sinh(ny);
          //tx=(sq(nx)+sq(ny)-1)/(sq(nx+1)+sq(ny));
          //ty=2*ny/(sq(nx+1)+sq(ny));
        }
      else if(map==4)                                    // Transform =(z_1)/(z+1)
        {
          nx=nx/1.5;
          ny=ny/1.5;
          tx=(sq(nx)+sq(ny)-1)/(sq(nx+1)+sq(ny));
          ty=(2*ny)/(sq(nx+1)+sq(ny));
        }
       stroke(cblue);
       fill(cred);
       circle(tx*fact,ty*fact,8);
       stroke(cred);
       fill(cblue);
       circle(-tx*fact,ty*fact,8);
    }
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function cosh(a)
{
  let res=(exp(a) +exp(-a))/2;
  return(res);
}

function sinh(a)
{
  var res=(exp(a) -exp(-a))/2;
  return(res);
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function mulc(cp1,cp2)
{
  let cp=createVector(0,0);
  cp.x=cp1.x*cp2.x - cp1.y*cp2.y;
  cp.y= cp1.x*cp2.y+cp1.y*cp2.x;
  return(cp);
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function tempo(tmp)
{
 let mm=millis();
 let m=0;
 let dif=0;
 let _wG_1 = 0; while ((dif<tmp) && ++_wG_1 < 20000)
   {
     m=millis();
     dif=m-mm;
   }
}

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function affstring(str,x,y,dx,dy)                                
{
  var xs=x+dx;
  var ys=y+dy;
  text(str,xs,ys);
}

